import { describe, expect, it } from 'vitest';
import { baseConfig } from '../../src/data/config';
import typeChartFile from '../../src/data/generated/typeChart.json';
import { GAME_TYPES } from '../../src/domain';

/**
 * The 18x18 type chart generated by `tools/fetch-data` from PokéAPI (4H-B1, ADR-047). The game does
 * not read it yet (the 4H-B2 does): these tests pin that the data is right, so the migration starts
 * from a chart that is known to be complete and true to the games.
 */
const chart = typeChartFile.chart as Record<string, Record<string, number>>;
const types = typeChartFile.types as string[];

describe('typeChart.json (generated from PokéAPI)', () => {
  it('has the 18 types of the games, once each', () => {
    expect(types).toHaveLength(18);
    expect(new Set(types).size).toBe(18);
    expect(Object.keys(chart).sort()).toEqual([...types].sort());
  });

  it('is complete: every attacker has a value for every defender, and only 0, 0.5, 1 or 2', () => {
    for (const attacker of types) {
      expect(Object.keys(chart[attacker] ?? {}).sort()).toEqual([...types].sort());
      for (const defender of types) {
        expect([0, 0.5, 1, 2]).toContain(chart[attacker]?.[defender]);
      }
    }
  });

  it('matches the games on well-known pairs', () => {
    const at = (a: string, d: string) => chart[a]?.[d];
    expect(at('fire', 'grass')).toBe(2);
    expect(at('water', 'fire')).toBe(2);
    expect(at('electric', 'water')).toBe(2);
    expect(at('electric', 'ground')).toBe(0); // the immunity the game softens (x0.25)
    expect(at('ground', 'electric')).toBe(2);
    expect(at('rock', 'fire')).toBe(2);
    expect(at('normal', 'ghost')).toBe(0);
    expect(at('ghost', 'normal')).toBe(0);
    expect(at('fighting', 'ghost')).toBe(0);
    expect(at('psychic', 'dark')).toBe(0);
    expect(at('dragon', 'fairy')).toBe(0);
    expect(at('fairy', 'dragon')).toBe(2);
    expect(at('ice', 'dragon')).toBe(2);
    expect(at('steel', 'fairy')).toBe(2);
    expect(at('poison', 'steel')).toBe(0);
    expect(at('flying', 'ground')).toBe(1); // flying does nothing special to ground; ground-on-flying is the 0
    expect(at('ground', 'flying')).toBe(0);
  });

  it('has the right number of immunities (there are exactly 8 in the games)', () => {
    let zeros = 0;
    for (const a of types) for (const d of types) if (chart[a]?.[d] === 0) zeros += 1;
    expect(zeros).toBe(8);
  });

  it('agrees with the 4x4 chart the game uses today on the four types it has', () => {
    for (const a of GAME_TYPES) {
      for (const d of GAME_TYPES) {
        expect(baseConfig.typeChart[a][d]).toBe(chart[a]?.[d]);
      }
    }
  });

  it('gives every type except Normal something it is strong against, and every type a weakness', () => {
    // Normal hits nothing for double in the games; every other type does.
    const strong = types.filter((t) => Object.values(chart[t] ?? {}).some((v) => v === 2));
    expect(types.filter((t) => !strong.includes(t))).toEqual(['normal']);
    for (const t of types) {
      expect(Object.values(chart[t] ?? {}).some((v) => v < 1)).toBe(true);
    }
  });
});
